insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-pe-261","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Hydrogen bonding is important for the hydrides of nitrogen, oxygen and fluorine, the smallest and most electronegative","options":["alkali metals","first-row non-metals","lanthanoids","noble gases"],"answer_index":1,"explanation":"Only N, O and F are small and electronegative enough for strong intermolecular hydrogen bonds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-262","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium burns in air to give mainly the monoxide Li₂O, whereas sodium readily forms the","options":["hydride only","peroxide","ozonide exclusively","nitride vapour"],"answer_index":1,"explanation":"The small Li⁺ ion is stabilised by the small O²⁻ ion; larger Na⁺ prefers the peroxide O₂²⁻.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-263","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Carbon–carbon single bonds are much stronger than silicon–silicon bonds, so catenation is far more characteristic of","options":["silicon","carbon","lead","tin"],"answer_index":1,"explanation":"The short, strong C–C bond and the inability of C to use d orbitals make long carbon chains uniquely stable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-264","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Boron forms electron-deficient compounds such as B₂H₆, a behaviour not typical of","options":["boron itself","aluminium alkyls in the same simple way","all p-block metals","helium"],"answer_index":1,"explanation":"Tiny boron has fewer valence orbitals than it needs for ordinary 2c–2e bonds, so it uses 3c–2e bridges.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-265","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine shows only the −1 oxidation state in its compounds, whereas chlorine can show","options":["only −1 as well","several positive oxidation states","the +8 state in ClF₈","no covalent compounds"],"answer_index":1,"explanation":"F is the most electronegative element and has no vacant d orbitals, so it never takes a positive OS.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-266","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium resembles magnesium more than sodium because Li⁺ and Mg²⁺ have similar charge-to-radius ratios, giving both a","options":["low polarising power","high polarising power","closed 3d¹⁰ shell","gaseous metallic lattice"],"answer_index":1,"explanation":"The two ions polarise anions strongly, so their oxides, fluorides and organometallic compounds look alike — the diagonal relationship.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-267","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Periodicity of properties arises because similar valence-shell configurations recur at regular intervals of","options":["atomic mass only","atomic number","neutron number","mass defect"],"answer_index":1,"explanation":"Each time a given ns / np pattern repeats, the chemistry of that group reappears.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-268","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Effective nuclear charge experienced by a valence electron is written $Z_{\\mathrm{eff}}=Z-\\sigma$, where $\\sigma$ is the","options":["atomic mass","screening constant","mass number","group number"],"answer_index":1,"explanation":"Inner electrons cancel part of Z; the remainder is the effective nuclear charge felt by the outer electron.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-269","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Inner electrons shield valence electrons from the full attraction of the","options":["neighbouring atoms","nucleus","neutron cloud","crystal field"],"answer_index":1,"explanation":"Screening (shielding) is the reason Zeff is smaller than Z.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-270","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Effective nuclear charge felt by the outermost electron","options":["falls across a period","increases across a period","is zero for all metals","equals the mass number"],"answer_index":1,"explanation":"Electrons are added to the same shell, which screens poorly, so Zeff climbs left to right.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
    answer_index int,
    explanation text,
    images jsonb,
    source jsonb,
    difficulty text,
    concept_id text,
    appear_count int,
    years jsonb,
    exams jsonb,
    verified boolean
  )
on conflict (question_id) do update set
  appear_count = excluded.appear_count,
  years = excluded.years,
  exams = excluded.exams,
  verified = excluded.verified;